\label{def:relational interpretation}
A \emph{(relational) interpretation} is a triple $\sigma = (S, \mathsf{eval}, \mathsf{sat})$ where $S$ is a set, $\mathsf{eval}: \Sigma \to \mathcal{P}(S \times S)$ and $\mathsf{sat}: T \to \mathcal{P}(S)$.
Each interpretation \(\sigma\) gives rise to a semantics $\semrel{-}_\sigma: \mathsf{GExp} \to \mathcal{P}(S \times S)$, as follows:
\begin{align*}
\semrel{0}_\sigma &= \emptyset
    & \semrel{\overline{a}}_\sigma &= \semrel{1}_\sigma \setminus \semrel{a}_\sigma \\
\semrel{1}_\sigma &= \{ (s, s) : s \in S \}
    & \semrel{p}_\sigma &= \mathsf{eval}(p) \\
\semrel{t}_\sigma &= \{ (s, s) : s \in \mathsf{sat}(t) \}
    & \semrel{e +_b f}_\sigma &= \semrel{b}_\sigma \circ \semrel{e}_\sigma \cup \semrel{\overline{b}}_\sigma \circ \semrel{f}_\sigma \\
\semrel{b \wedge c}_\sigma &= \semrel{b}_\sigma \cap \semrel{c}_\sigma
    & \semrel{e \cdot f}_\sigma &= \semrel{e}_\sigma \circ \semrel{f}_\sigma \\
\semrel{b \vee c}_\sigma &= \semrel{b}_\sigma \cup \semrel{c}_\sigma
    & \semrel{e^{(b)}}_\sigma &= {(\semrel{b}_\sigma \circ \semrel{e}_\sigma)}^* \circ \semrel{\overline{b}}_\sigma
\end{align*}
Here we use \(\circ\) for relation composition and ${}^*$ for reflexive transitive closure.

\begin{align*}
    \semrel{0}_\sigma &= \emptyset
        & \semrel{\overline{a}}_\sigma &= \semrel{1}_\sigma \setminus \semrel{a}_\sigma \\
    \semrel{1}_\sigma &= \{ (s, s) : s \in S \}
        & \semrel{p}_\sigma &= \mathsf{eval}(p) \\
    \semrel{t}_\sigma &= \{ (s, s) : s \in \mathsf{sat}(t) \}
        & \semrel{e +_b f}_\sigma &= \semrel{b}_\sigma \circ \semrel{e}_\sigma \cup \semrel{\overline{b}}_\sigma \circ \semrel{f}_\sigma \\
    \semrel{b \wedge c}_\sigma &= \semrel{b}_\sigma \cap \semrel{c}_\sigma
        & \semrel{e \cdot f}_\sigma &= \semrel{e}_\sigma \circ \semrel{f}_\sigma \\
    \semrel{b \vee c}_\sigma &= \semrel{b}_\sigma \cup \semrel{c}_\sigma
        & \semrel{e^{(b)}}_\sigma &= {(\semrel{b}_\sigma \circ \semrel{e}_\sigma)}^* \circ \semrel{\overline{b}}_\sigma
    \end{align*}

