\label{lem:finer}
        Let \(e_1, e_2 \in \mathsf{GExp}^-\).
        If \(e_1 \mathrel{\raisebox{0.1em}{\(\underline{\leftrightarrow}\)}} e_2\), then \(\mathcal{L}(e_1) = \mathcal{L}(e_2)\).

\label{thm:soundness}
        For any \(e_1, e_2 \in \mathsf{GExp}^-\),
        \begin{enumerate}
            \item If \(e_1 \equiv_\dagger e_2\), then \(e_1 \mathrel{\raisebox{0.1em}{\(\underline{\leftrightarrow}\)}} e_2\).
            \item If \(e_1 \equiv e_2\), then \(e_1 \sim_{\mathcal{L}} e_2\).
        \end{enumerate}

