\label{def:p bisim}
        Given labelled transition systems \((S, t)\) and \((T, u)\), a \emph{bisimulation} between them is a relation \(R \subseteq S \times T\) s.t.\ for any \(x \mathrel{R} y\) and \(\alpha p \in \mathsf{At}\cdot \Sigma\),
        \begin{enumerate}
            \item \(x \tr{\alpha p} \checkmark\) if and only if \(y \tr{\alpha  p} \checkmark\),
            \item if \(x \tr{\alpha p} x'\), then there exists a $y'$ such that \(x' \mathrel{R} y'\) and \(y \tr{\alpha p} y'\), and
            \item if \(y \tr{\alpha p} y'\), then there exists an $x'$ such that \(x' \mathrel{R} y'\) and \(x \tr{\alpha p} x'\).
        \end{enumerate}
       As before, we denote the largest bisimulation by $\mathrel{\raisebox{0.1em}{\(\underline{\leftrightarrow}\)}}$.
       That is, we call \(x\) and \(y\) \emph{bisimilar} and write \(x \mathrel{\raisebox{0.1em}{\(\underline{\leftrightarrow}\)}} y\) if \(x \mathrel{R} y\) for some bisimulation $R$.

\label{lem:bisim iff bisim}
    Let \(x, y \in X\), and \((X, h)\) be a skip-free automaton.
    Then \(x \mathrel{\raisebox{0.1em}{\(\underline{\leftrightarrow}\)}} y\) in \((X, h)\) if and only if \(x \mathrel{\raisebox{0.1em}{\(\underline{\leftrightarrow}\)}} y\) in \(\mathsf{grph}_*(X, h)\).

\label{lem:gtr is good stuff}
    The graph of the translation function \(\operatorname{gtr}\) is a bisimulation of labelled transition systems between $\mathsf{grph}_*(\mathsf{GExp}^-, \partial)$ and $(\mathsf{StExp}, \tau)$.
    Consequently, \(e_1 \mathrel{\raisebox{0.1em}{\(\underline{\leftrightarrow}\)}} e_2\) in $\mathsf{grph}_*(\mathsf{GExp}^-, \partial)$ if and only if \(\operatorname{gtr}(e_1) \mathrel{\raisebox{0.1em}{\(\underline{\leftrightarrow}\)}} \operatorname{gtr}(e_2)\) in $(\mathsf{StExp}, \tau)$.

\label{lem:rtg is also good stuff}
    Let \(r, s \in \mathsf{Det}\).
    If \(r \equiv_* s\), then \(\operatorname{rtg}(r) \equiv_\dagger \operatorname{rtg}(s)\).

