We define $\widehat{\mathcal{L}}: \mathsf{GExp} \to \mathcal{P}(\mathsf{At} \cdot (\Sigma \cdot \mathsf{At})^*)$ inductively, as follows:
\begin{mathpar}
    \widehat{\mathcal{L}}(b) = \{ \alpha \in \mathsf{At} \mid \alpha \leq b \}
    \and
    \widehat{\mathcal{L}}(p) = \{ \alpha{}p\beta \mid \alpha, \beta \in \mathsf{At} \}
    \and
    \widehat{\mathcal{L}}(e \cdot f) = \widehat{\mathcal{L}}(e) \diamond \widehat{\mathcal{L}}(f)
    \\
    \widehat{\mathcal{L}}(e +_b f) = \widehat{\mathcal{L}}(b) \diamond \widehat{\mathcal{L}}(e) \cup \widehat{\mathcal{L}}(\overline{b}) \diamond \widehat{\mathcal{L}}(f)
    \and
    \widehat{\mathcal{L}}(e^{(b)}) = (\widehat{\mathcal{L}}(b) \diamond \widehat{\mathcal{L}}(e))^{(*)} \diamond \widehat{\mathcal{L}}(\overline{b})
\end{mathpar}

