\label{def:well-layeredness}
	An LTS \((X, \tau)\) is said to be \emph{well-layered} if it has an entry/body labelling \((X, \mathrel{\raisebox{-2pt}{\color{blue}\(\to_{\mathsf{e}}\)}}, \mathrel{\raisebox{-2pt}{\(\to_{\mathsf{b}}\)}})\) that satisfies the following conditions.
	\begin{enumerate}
		\item (\emph{local finiteness}) For any \(x \in X\), \(\langle x \rangle\) is finite.
		\item (\emph{flatness}) For any \(x,y \in X\), if \(x \mathrel{\raisebox{-2pt}{\color{blue}\(\to_{\mathsf{e}}\)}} y\), then \(\neg (x \mathrel{\raisebox{-2pt}{\(\to_{\mathsf{b}}\)}} y)\).
		\item (\emph{full specification}) For any \(x,y \in X\),
		\begin{enumerate}
			\item \(\neg(x \mathrel{\raisebox{-2pt}{\(\to_{\mathsf{b}}\)}}^+ x)\) (there are no body loops), and
			\item if \(x \mathrel{\raisebox{-2pt}{\color{blue}\(\to_{\mathsf{e}}\)}} y\) and \(y \neq x\), then \(y \to^+ x\) (every entry transition is a loop entry transition).
		\end{enumerate}
		\item (\emph{layeredness}) The graph \((X, \mathrel{\curvearrowright})\) is acyclic.
		\item (\emph{goto-free}) If \(x \mathrel{\curvearrowright} y\), then \(\neg(y \to \checkmark)\).
	\end{enumerate}
	If \((X, \mathrel{\raisebox{-2pt}{\color{blue}\(\to_{\mathsf{e}}\)}}, \mathrel{\raisebox{-2pt}{\(\to_{\mathsf{b}}\)}})\) satifies these conditions, we say that \((X, \mathrel{\raisebox{-2pt}{\color{blue}\(\to_{\mathsf{e}}\)}}, \mathrel{\raisebox{-2pt}{\(\to_{\mathsf{b}}\)}})\) is a \emph{layering witness} for \((X, \tau)\).

\label{thm:closure under homomorphic images}
	Let \((X, \tau_X)\) be a well-layered LTS and \(h\colon (X, \tau_X) \to (Y, \tau_Y)\) be a surjective coalgebra homomorphism.
	Then \((Y, \tau_Y)\) is also well-layered.

